 static object Read(Type t,string path){var s=FormatterServices.GetUninitializedObject(t);using(var r=new BinaryReader(File.OpenRead(path)))t.GetMethod("ReadHeader",F).Invoke(s,new object[]{r});return s;}
 public static void Check(Assembly asm,string root,int lod,object plan,object model,float delta,int meshIndex){
 Type T(string n)=>asm.GetType("BridgeBuilder.Bridges."+n,true);var tiletype=T("MovableStructureTiles");var st=tiletype.GetMethod("NativeSurface",F).ReturnType;var prepared=asm.GetType("BridgeBuilder.Runtime.BridgePreparedMaterials",true);prepared.GetField("_root",F).SetValue(null,Path.GetFullPath(Path.Combine(root,"../../../../assets/Materials")));var cache=(IDictionary)prepared.GetField("Surfaces",F).GetValue(null);
 var repo=Path.GetFullPath(Path.Combine(root,"../../../.."));foreach(var path in Directory.GetFiles(Path.Combine(repo,"assets/Materials/Lift05"),"*.Surface",SearchOption.AllDirectories)){string key="Lift05/"+path.Substring(Path.Combine(repo,"assets/Materials/Lift05").Length+1).Replace('\\','/');if(cache.Contains(key))continue;var s=Read(st,path);string sid=File.ReadAllText(path+".cid").Trim();Id(s,sid);cache.Add(key,s);if(!identities.ContainsKey(s))identities.Add(s,sid);}
 string cid=meshIndex==1?"24cf998eda84a65dcd7334a7b0b02b90":lod==2?"d68e4bd81e9e8a61ded03d2ac017680f":"78fda4223742d922d34b5cc2331eb65f";string input=Path.Combine(root,meshIndex==1?"glass/native.Surface":"raw/lod"+lod+".Surface");if(!sources.TryGetValue(cid,out var source)){source=Read(st,input);Id(source,cid);sources.Add(cid,source);identities.Add(source,cid);}
 var tiles=Activator.CreateInstance(tiletype,F,null,new object[]{"Lift05"},null);using(var hash=System.Security.Cryptography.SHA256.Create())((IDictionary)tiletype.GetField("_sourceDigests",F).GetValue(tiles)).Add(source,BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(input))).Replace("-","").ToLowerInvariant());
